CREATE TABLE oauth_access_token (id TEXT PRIMARY KEY NOT NULL, token TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES oauth_client(client_id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, authorization_code_id TEXT, metadata TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX idx_oauth_access_token_code ON oauth_access_token(authorization_code_id);
CREATE INDEX idx_oauth_access_token_client ON oauth_access_token(client_id);
CREATE INDEX idx_oauth_access_token_user ON oauth_access_token(user_id);
CREATE INDEX idx_oauth_access_token_session ON oauth_access_token(session_id);
CREATE TABLE oauth_refresh_token (id TEXT PRIMARY KEY NOT NULL, token TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES oauth_client(client_id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, authorization_code_id TEXT, metadata TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX idx_oauth_refresh_token_code ON oauth_refresh_token(authorization_code_id);
CREATE INDEX idx_oauth_refresh_token_client ON oauth_refresh_token(client_id);
CREATE INDEX idx_oauth_refresh_token_user ON oauth_refresh_token(user_id);
CREATE INDEX idx_oauth_refresh_token_session ON oauth_refresh_token(session_id);
